-- 1. Grand Canal Suite --
insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000010000', E'Grand Canal Suite', E'97 m² / 1,044 sq ft', 97, 97, E'Up to 4 guests when configured as two bedrooms', E'King-size bed; can be configured into two bedrooms', E'Grand Canal', null, E'With magnificent eye-level views of the Grand Canal, the 97 square metre (1,044 square feet) Grand Canal Suite offers an elegant and contemporary retreat in the heart of the city. The expansive interior comprises a king-sized bedroom and a separate sitting room, each offering a different view: in the former, large picture windows frame the canal; in the latter, the filigree arched window creates drama and offers a different aspect. Both rooms are flooded with light and authentic, characterful features. The suite can also be configured into two bedrooms, ideal for families with children.', array[E'Eye-level views of the Grand Canal', E'Separate sitting room with filigree arched window', E'Can be configured into two bedrooms'], null, '{}'::text[], 1)
on conflict (id) do update set name = excluded.name, size = excluded.size, size_m2_min = excluded.size_m2_min, size_m2_max = excluded.size_m2_max, max_occupancy = excluded.max_occupancy, beds = excluded.beds, view = excluded.view, units = excluded.units, description = excluded.description, highlights = excluded.highlights, description_pt = excluded.description_pt, highlights_pt = excluded.highlights_pt, sort_order = excluded.sort_order;
