insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000020000', E'Alcova Tiepolo Suite', E'103 m² / 1,108 sq ft', 103, 103, E'Up to 2 guests', E'Separate bedroom with king-size bed', E'Garden Terrace', null, E'The 103 square metre (1,108 square feet) Alcova Tiepolo Suite offers the chance to stay among remarkable 18th-century frescoes by Giovanni Battista Tiepolo, described as the greatest decorative painter of 18th-century Europe. Gilded ceilings and tall windows frame views of the Garden Terrace, and an ornately painted sitting room with a fireplace is the place to retire after an evening in the city. A separate king-sized bedroom with en suite and dressing room provides space and privacy.', array[E'Original 18th-century Tiepolo frescoes', E'Gilded ceilings and marble fireplaces', E'Separate ornately painted sitting room', E'Views over the Garden Terrace'], null, '{}'::text[], 2)
