-- 3. Papadopoli Stanza Canal Grande --
insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000030000', E'Papadopoli Stanza Canal Grande', E'73 m² / 785 sq ft', 73, 73, E'Up to 2 guests', E'King-size bed', E'Garden Terrace and Grand Canal', null, E'Boasting high ceilings and authentic decorative frescoes, the 73 square metre (785 square feet) Papadopoli Stanza Canal Grande is a private sanctuary that frames views of the Garden Terrace and the Grand Canal. The room offers a combined living area with fireplace and a bedroom with king-sized bed, and through tall wooden doors an expansive light-flooded bathroom with deep-soaking bathtub makes the most of the vistas.', array[E'Frescoes in bedroom and bathroom', E'Fireplace', E'Deep-soaking bathtub facing the canal'], null, '{}'::text[], 3)
