-- 5. Sansovino Stanza --
insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000050000', E'Sansovino Stanza', E'75 m² / 807 sq ft', 75, 75, E'Up to 2 guests', E'King-size bed', E'Garden Terrace, partial Grand Canal from the bathroom', null, E'Originally entitled ''The Hall of Four Doors'', the 75 square metre (807 square feet) Sansovino Stanza features a historic 16th-century fireplace designed by Sansovino, wood panelling, a painted frieze and a carved ceiling. The room makes the most of its architectural details with a shared bedroom and living area adorned with silk wall coverings and chandeliers. Tall windows overlook the Garden Terrace, and partial views of the Grand Canal can be seen from the bathroom.', array[E'16th-century fireplace designed by Sansovino', E'Wood panelling, painted frieze and carved ceiling', E'Originally ''The Hall of Four Doors'''], null, '{}'::text[], 5)
