-- 6. Palazzo Stanza Canal Grande --
insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000060000', E'Palazzo Stanza Canal Grande', E'57 to 89 m² / 613 to 957 sq ft', 57, 89, E'Up to 2 guests', E'King-size bed', E'Grand Canal and Garden Terrace', null, E'With exceptional views of the Grand Canal and the Garden Terrace, the Palazzo Stanzas Canal Grande vary in size from 57 to 89 square metres (613 to 957 square feet), with some offering original architectural features. Elegant yet contemporary, the rooms have king-sized beds, a living space with writing desk, sofa or twin lounge chairs, and large windows that fill the space with light.', array[E'Views of the Grand Canal and the Garden', E'Some rooms keep original architectural details', E'The largest of the Rooms category'], null, '{}'::text[], 6)
