-- 9. Palazzo Bedroom --
insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000090000', E'Palazzo Bedroom', E'47 to 60 m² / 505 to 645 sq ft', 47, 60, E'Up to 2 guests', E'King-size bed', E'Private garden', null, E'Varying in size from 47 to 60 square metres (505 to 645 square feet), each Palazzo Bedroom is unique in layout and design, and all look onto the palazzo''s private garden below. Bright, airy and elegant, the rooms have king-sized beds with a combined living area and writing desk. Contemporary furnishings create a modern space without compromising the history and architecture of the building, and a large bathroom with bathtub, separate shower and twin vanities ensures space and privacy.', array[E'Each one unique in layout and design', E'Views of the private garden', E'The entry category of the house'], null, '{}'::text[], 9)
