-- 11. The Coccina's Apartment --
insert into ops_room_types (supplier_id, id, name, size, size_m2_min, size_m2_max, max_occupancy, beds, view, units, description, highlights, description_pt, highlights_pt, sort_order)
values (E'39000000-0000-0000-0000-000000000000', E'39000000-0000-0000-0000-000000110000', E'The Coccina''s Apartment', E'290 m² / 3,122 sq ft', 290, 290, E'Up to 6 guests', E'3 king-size bedrooms, each en suite', E'Grand Canal and the Canal Garden', E'The whole fourth floor, private elevator', E'On the fourth floor of the palazzo and reached by a private elevator, the Coccina''s Apartment has three free-standing bedrooms over a total of 290 square metres (3,122 square feet), all with en-suite bathrooms and king-size beds, a private living room and views over the Grand Canal and the Canal Garden. The design includes works by several of Italy''s greatest artists, frescoes and reliefs among them; contemporary furnishings complement silk wall coverings, chandeliers, wood panelling, chinoiserie and painted ceilings.', array[E'The whole fourth floor, with private elevator', E'Three free-standing bedrooms', E'Frescoes, reliefs, silk wall coverings and painted ceilings', E'Chapel Lounge'], null, '{}'::text[], 11)
