-- =====================================================================
-- 2 · BELMOND HOTEL CIPRIANI, com o Palazzo Vendramin
-- =====================================================================
insert into ops_suppliers (id, name, category, subcategories, business_suite, status, region, city, address, website, languages, name_rule, vat_status, vat_number, rates_valid_for, accommodation_summary, accommodation_notes, capacities, highlights, tags, summary, open_points, internal_notes)
values (E'49000000-0000-0000-0000-000000000000', E'Belmond Hotel Cipriani', E'Hotel / Accommodation', array[E'City hotel', E'Historic building', E'Resort'], array[E'TL Selected Stays', E'MICE e Exclusive Events'], E'To test', E'Other', E'Venezia (Giudecca)', E'Giudecca 10, 30133 Venezia', E'https://www.belmond.com/en/hotels/europe/italy/hotel-cipriani-venice', array[E'Italian', E'English'], E'Show supplier name', E'not stated', null, null, E'79 accommodations: 55 rooms, 20 suites and 4 signature suites, published in four tiers — Double Rooms 21 to 46 m², Junior Suites 33 to 65 m², Suites 50 to 80 m² and Signature Suites 107 to 188 m². The suites were redesigned by Peter Marino. Belmond does not publish the individual category names on the property pages.', E'18th-century design with lagoon views over Venice. Marbled bathrooms; private balconies, terraces or gardens in several categories. The four Signature Suites are the Laguna and Serenissima, which face the water, and the Palladio and Dogaressa, which carry original artwork and 18th-century antiques.', E'Event venues for 10 to 300 people, including the Granaries of the Republic. Weddings, anniversaries, birthdays and family celebrations.', array[E'Giudecca Island, across the water from San Marco: the quiet side of Venice', E'Opened in 1958 by Giuseppe Cipriani, for the jetset who wanted to be near San Marco and away from the crowd', E'Palazzo Vendramin, a 15th-century residence beside the hotel, with the hotel''s pool and gardens next door', E'The largest swimming pool in Venice, heated and outdoors', E'Dior Spa Hotel Cipriani', E'Michelin-starred dining at Oro, renovated by Peter Marino, with lagoon views', E'Four restaurants and three bars: Oro, Cip''s Club on the water, Il Porticciolo by the pool, Bar Gabbiano, Ristorante San Giorgio and Bacaro Dior', E'Casanova Gardens, tennis court, children''s club, boutiques and a private marina', E'Complimentary five-minute shuttle launch to Piazza San Marco, running around the clock', E'30 minutes by water taxi from Marco Polo airport; 20 minutes from Santa Lucia station'], array[E'Venice', E'Giudecca', E'Belmond', E'Palazzo Vendramin', E'pool', E'Dior Spa', E'Michelin', E'wedding venue'], E'The hotel Giuseppe Cipriani built on Giudecca in 1958 for the people who wanted San Marco in sight and the crowd out of earshot, reached by private launch across the lagoon. 79 rooms and suites in 18th-century design, the suites redesigned by Peter Marino, with the largest pool in Venice, the Casanova Gardens, a Dior spa and Michelin-starred dining at Oro. Palazzo Vendramin, a 15th-century residence beside the hotel, is the most private part of the house, with the hotel''s pool and gardens next door. Five minutes to Piazza San Marco by the hotel''s own boat.', array[E'CLOSED FROM 30 SEPTEMBER AND REOPENING 1 JUNE 2027, as the hotel''s own site states. Emily''s dates (2 to 5 July 2027) fall inside the season, but 2027 rates will be new rates.', E'PALAZZO VENDRAMIN IS NO LONGER A PUBLISHED CATEGORY. belmond.com lists only the four tiers, and the Vendramin appears in the photo captions of the Junior Suite and Double Room tiers. Her briefing offers ''Palazzo Vendramin at Hotel Cipriani · Vendramin Suite'' and quotes 17 rooms. Ask Belmond which rooms of the Vendramin wing sit in which tier before the rate goes out.', E'Individual category names and floor areas per category are not published; only the four tiers with size ranges are. Ask Belmond for the room fact sheet.', E'Net rates, cancellation policy and payment terms to the supplier not yet collected.', E'Photo usage not cleared: these are the hotel''s own website images, usage_cleared is false.'], E'Reservas +39 041 240 801 · central Belmond 1 800 237 1236.\nFicha montada do site oficial, outubro/26. O site publica QUATRO FAIXAS de acomodação com metragem e ocupação, e não as categorias uma por uma — mesmo desenho do Villa San Michele (0050), que é Belmond também. As fotos vêm do img.belmond.com, que responde CORS e encolhe no PDF.\nEntrou para a proposta da Emily (TL-053-26), como Palazzo Vendramin at Hotel Cipriani.\nStatus ''To test'' porque não há tarifa net lançada nem venda registrada aqui.')
on conflict (id) do update set name = excluded.name, category = excluded.category, subcategories = excluded.subcategories, business_suite = excluded.business_suite, status = excluded.status, region = excluded.region, city = excluded.city, address = excluded.address, website = excluded.website, languages = excluded.languages, name_rule = excluded.name_rule, vat_status = excluded.vat_status, vat_number = excluded.vat_number, rates_valid_for = excluded.rates_valid_for, accommodation_summary = excluded.accommodation_summary, accommodation_notes = excluded.accommodation_notes, capacities = excluded.capacities, highlights = excluded.highlights, tags = excluded.tags, summary = excluded.summary, open_points = excluded.open_points, internal_notes = excluded.internal_notes, updated_at = now();

